import { site } from '../../data/site.js';

export default function Terminal() {
  const linhas = site.terminal;
  return (
    <div className="terminal">
      <div className="term-barra">
        <span className="bolas" aria-hidden="true">
          <i />
          <i />
          <i />
        </span>
        <span className="rotulo">{site.handle}@portfolio — ~</span>
      </div>
      <div className="term-corpo">
        {linhas.map(([cmd, saida], i) => (
          <div key={cmd} className="term-par">
            <p className="cmd">
              <span className="prompt">&gt;</span> {cmd}
            </p>
            <p className="saida">
              {saida}
              {i === linhas.length - 1 && <span className="cursor" aria-hidden="true" />}
            </p>
          </div>
        ))}
      </div>
    </div>
  );
}
