import { useEffect, useRef } from 'react';
import { site } from '../../data/site.js';

// Comentários via GitHub Discussions
export default function Comentarios({ termo }) {
  const ref = useRef(null);
  const g = site.giscus;
  const ativo = Boolean(g.repo && g.repoId && g.categoryId);

  useEffect(() => {
    if (!ativo || !ref.current) return;
    ref.current.innerHTML = '';
    const s = document.createElement('script');
    s.src = 'https://giscus.app/client.js';
    s.async = true;
    s.crossOrigin = 'anonymous';
    const attrs = {
      'data-repo': g.repo,
      'data-repo-id': g.repoId,
      'data-category': g.category,
      'data-category-id': g.categoryId,
      'data-mapping': 'specific',
      'data-term': termo,
      'data-strict': '0',
      'data-reactions-enabled': '1',
      'data-emit-metadata': '0',
      'data-input-position': 'top',
      'data-theme': 'dark',
      'data-lang': 'pt',
    };
    Object.entries(attrs).forEach(([k, v]) => s.setAttribute(k, v));
    ref.current.appendChild(s);
  }, [ativo, termo, g]);

  if (!ativo) {
    return (
      <p className="aviso">
        Os comentários ainda não estão ativados. Preencha o bloco <code>giscus</code> em <code>src/data/site.js</code>{' '}
        (veja o LEIA-ME).
      </p>
    );
  }
  return <div ref={ref} />;
}
