import { useMemo } from 'react';
import { useSearchParams } from 'react-router-dom';
import FaixaTopicos from '../../components/FaixaTopicos/FaixaTopicos.jsx';
import PostCard from '../../components/PostCard/PostCard.jsx';
import { posts } from '../../lib/posts.js';
import { semAcento, useTitulo } from '../../lib/util.js';

const TIPOS = [
  ['artigo', 'Artigos'],
  ['tutorial', 'Tutoriais'],
  ['tudo', 'Tudo'],
];

export default function Artigos() {
  useTitulo('Artigos');
  const [params, setParams] = useSearchParams();
  const q = params.get('q') || '';
  const topico = params.get('topico') || '';
  const tipoParam = params.get('tipo') || '';
  const tipo = tipoParam || (q ? 'tudo' : 'artigo');

  function mudar(chave, valor) {
    const novo = new URLSearchParams(params);
    if (valor) novo.set(chave, valor);
    else novo.delete(chave);
    setParams(novo);
  }

  const lista = useMemo(
    () =>
      posts.filter((p) => {
        if (tipo !== 'tudo' && p.tipo !== tipo) return false;
        if (topico && p.topico !== topico) return false;
        if (q) {
          const alvo = semAcento(`${p.titulo} ${p.resumo} ${p.topico} ${p.corpo}`);
          if (!semAcento(q).split(/\s+/).every((t) => alvo.includes(t))) return false;
        }
        return true;
      }),
    [q, topico, tipo]
  );

  return (
    <>
      <FaixaTopicos />
      <section className="wrap sec">
        <header className="pagina-topo">
          <p className="rotulo acc">Publicações</p>
          <h1>Artigos</h1>
          <div className="filtros" role="group" aria-label="Filtrar por tipo">
            {TIPOS.map(([valor, texto]) => (
              <button
                key={valor}
                type="button"
                className="chip"
                aria-pressed={tipo === valor}
                onClick={() => mudar('tipo', valor === 'artigo' ? '' : valor)}
              >
                {texto}
              </button>
            ))}
          </div>
          <p className="rotulo" role="status">
            {lista.length} {lista.length === 1 ? 'resultado' : 'resultados'}
            {q && ` para “${q}”`}
            {topico && ` em ${topico}`}
          </p>
        </header>
        {lista.length === 0 ? (
          <p className="aviso">Nada encontrado. Tente outro termo ou limpe os filtros.</p>
        ) : (
          <div className="cards">
            {lista.map((p, i) => (
              <PostCard key={p.slug} post={p} fig={(i % 4) + 2} />
            ))}
          </div>
        )}
      </section>
    </>
  );
}
