import ReactMarkdown from 'react-markdown';
import { Link, useParams } from 'react-router-dom';
import Arte from '../../components/Arte/Arte.jsx';
import Comentarios from '../../components/Comentarios/Comentarios.jsx';
import Seta from '../../components/Seta/Seta.jsx';
import { formatarData, posts, tutoriais } from '../../lib/posts.js';
import { hash, useTitulo } from '../../lib/util.js';
import NaoEncontrado from '../NaoEncontrado/NaoEncontrado.jsx';

const componentes = {
  a: ({ href, children }) =>
    /^https?:/.test(href || '') ? (
      <a href={href} target="_blank" rel="noreferrer">
        {children}
      </a>
    ) : (
      <a href={href}>{children}</a>
    ),
};

export default function Post() {
  const { slug } = useParams();
  const post = posts.find((p) => p.slug === slug);
  useTitulo(post?.titulo);
  if (!post) return <NaoEncontrado />;

  const idx = post.tipo === 'tutorial' ? tutoriais.findIndex((p) => p.slug === slug) : -1;
  const anterior = idx > 0 ? tutoriais[idx - 1] : null;
  const proximo = idx >= 0 && idx < tutoriais.length - 1 ? tutoriais[idx + 1] : null;

  return (
    <article className="wrap post">
      <header className="post-topo">
        <p className="rotulo acc">
          {post.tipo === 'tutorial' ? 'Tutorial' : 'Artigo'} · {post.topico}
        </p>
        <h1>{post.titulo}</h1>
        {post.resumo && <p className="dek">{post.resumo}</p>}
        <p className="rotulo">
          {formatarData(post.data)} · {post.minutos} MIN DE LEITURA
        </p>
      </header>

      <div className="post-arte">
        <Arte tipo={post.arte} semente={hash(post.slug)} fig={1} />
      </div>

      <div className="prose">
        <ReactMarkdown components={componentes}>{post.corpo}</ReactMarkdown>
      </div>

      {(anterior || proximo) && (
        <nav className="post-nav" aria-label="Navegação entre tutoriais">
          {anterior ? (
            <Link className="lnk" to={`/artigo/${anterior.slug}`}>
              ← {anterior.titulo}
            </Link>
          ) : (
            <span />
          )}
          {proximo && (
            <Link className="lnk" to={`/artigo/${proximo.slug}`}>
              {proximo.titulo} <Seta />
            </Link>
          )}
        </nav>
      )}

      <section className="post-comentarios" aria-labelledby="comentarios">
        <h2 id="comentarios" className="rotulo acc">Comentários</h2>
        <Comentarios termo={`post:${post.slug}`} />
      </section>
    </article>
  );
}
