function separar(texto) {
  const m = texto.match(/^---\r?\n([\s\S]*?)\r?\n---\r?\n?([\s\S]*)$/);
  if (!m) return { meta: {}, corpo: texto };
  const meta = {};
  for (const linha of m[1].split(/\r?\n/)) {
    const i = linha.indexOf(':');
    if (i < 0) continue;
    const chave = linha.slice(0, i).trim();
    const valor = linha.slice(i + 1).trim().replace(/^["']|["']$/g, '');
    meta[chave] = valor;
  }
  return { meta, corpo: m[2] };
}

export const posts = Object.entries(brutos)
  .map(([caminho, texto]) => {
    const { meta, corpo } = separar(texto);
    const slug = caminho.split('/').pop().replace(/\.md$/, '');
    const palavras = corpo.split(/\s+/).filter(Boolean).length;
    return {
      slug,
      titulo: meta.titulo || slug,
      resumo: meta.resumo || '',
      data: meta.data || '',
      tipo: meta.tipo === 'tutorial' ? 'tutorial' : 'artigo',
      topico: meta.topico || 'Geral',
      ordem: Number(meta.ordem || 0),
      destaque: meta.destaque === 'true',
      arte: meta.arte || 'rings',
      minutos: Math.max(1, Math.round(palavras / 200)),
      corpo,
    };
  })
  .sort((a, b) => b.data.localeCompare(a.data));

export const artigos = posts.filter((p) => p.tipo === 'artigo');
export const tutoriais = posts.filter((p) => p.tipo === 'tutorial').sort((a, b) => a.ordem - b.ordem);
export const destaque = posts.find((p) => p.destaque) || artigos[0] || posts[0];

const MESES = ['JAN', 'FEV', 'MAR', 'ABR', 'MAI', 'JUN', 'JUL', 'AGO', 'SET', 'OUT', 'NOV', 'DEZ'];
export function formatarData(iso) {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(iso || '');
  if (!m) return '';
  return `${m[3]} ${MESES[Number(m[2]) - 1]} ${m[1]}`;
}
