import { useId, useMemo } from 'react';
import { rng } from '../../lib/util.js';

// Paleta das ilustrações (as mesmas cores do painel)
const C = {
  fundo: '#0a0b0f',
  pontos: '#15171e',
  aresta: '#242732',
  no: '#343846',
  anel: '#262935',
  barra: '#282b38',
  acento: '#e4402f',
  acentoEscuro: '#70241e',
  tinta: '#ece9e3',
  regua: '#2e313c',
};

function Legenda({ x, y, texto, direita = false }) {
  const w = texto.length * 6.7 + 12;
  const x0 = direita ? x - w : x;
  return (
    <g>
      <rect x={x0} y={y} width={w} height="18" fill={C.fundo} />
      <text x={x0 + 6} y={y + 13} className="arte-txt">
        {texto}
      </text>
    </g>
  );
}

function Cruz({ x, y, r = 7 }) {
  return (
    <g stroke={C.regua} strokeWidth="1">
      <line x1={x - r} y1={y} x2={x + r} y2={y} />
      <line x1={x} y1={y - r} x2={x} y2={y + r} />
    </g>
  );
}

function Pontos({ id, w, h, passo = 24 }) {
  return (
    <>
      <defs>
        <pattern id={id} width={passo} height={passo} patternUnits="userSpaceOnUse">
          <circle cx={passo / 2} cy={passo / 2} r="1.1" fill={C.pontos} />
        </pattern>
      </defs>
      <rect width={w} height={h} fill={`url(#${id})`} />
    </>
  );
}

/* ---------------------------------------------------------- rede (destaque) */
function montarRede(s0, w, h) {
  const excluir = (x, y) => (x < 270 && y < 52) || (x > w - 270 && y > h - 52);
  let res = null;

  for (let s = s0; s < s0 + 60; s++) {
    const r = rng(s);
    const pts = [];
    let t = 0;
    while (pts.length < 46 && t < 30000) {
      t++;
      const x = 34 + r() * (w - 68);
      const y = 34 + r() * (h - 68);
      if (excluir(x, y)) continue;
      if (pts.every(([px, py]) => (x - px) ** 2 + (y - py) ** 2 >= 62 * 62)) pts.push([x, y]);
    }
    let inicio = 0;
    let melhor = Infinity;
    pts.forEach((p, i) => {
      const v = p[0] + Math.abs(p[1] - h * 0.55) * 0.4;
      if (v < melhor) {
        melhor = v;
        inicio = i;
      }
    });
    const caminho = [inicio];
    for (;;) {
      const cur = pts[caminho[caminho.length - 1]];
      let prox = -1;
      let pv = Infinity;
      pts.forEach((p, i) => {
        if (caminho.includes(i) || p[0] <= cur[0] + 28) return;
        const dd = Math.hypot(p[0] - cur[0], p[1] - cur[1]);
        if (dd >= 175) return;
        const v = dd + Math.abs(p[1] - h * 0.5) * 0.35;
        if (v < pv) {
          pv = v;
          prox = i;
        }
      });
      if (prox < 0) break;
      caminho.push(prox);
    }
    res = { pts, caminho };
    const extensao = pts[caminho[caminho.length - 1]][0] - pts[caminho[0]][0];
    if (caminho.length >= 7 && extensao > w * 0.68) break;
  }

  const { pts, caminho } = res;
  const pp = caminho.map((i) => pts[i]);

  // arestas: cada nó liga aos 3 vizinhos mais próximos (se estiverem perto)
  const conj = new Set();
  pts.forEach((p, i) => {
    pts
      .map((q, j) => [j, Math.hypot(p[0] - q[0], p[1] - q[1])])
      .filter(([j]) => j !== i)
      .sort((a, b) => a[1] - b[1])
      .slice(0, 3)
      .forEach(([j, dist]) => {
        if (dist < 150) conj.add(i < j ? `${i}-${j}` : `${j}-${i}`);
      });
  });
  const lista = [...conj].map((k) => k.split('-').map(Number));

  // rótulos de endereço sem tocar o caminho nem os nós
  const amostras = (a, b, passo) => {
    const n = Math.max(2, Math.floor(Math.hypot(b[0] - a[0], b[1] - a[1]) / passo));
    return Array.from({ length: n + 1 }, (_, t) => [
      a[0] + ((b[0] - a[0]) * t) / n,
      a[1] + ((b[1] - a[1]) * t) / n,
    ]);
  };
  const ptsCaminho = pp.slice(0, -1).flatMap((a, i) => amostras(a, pp[i + 1], 6));
  const ptsArestas = lista.flatMap(([i, j]) => amostras(pts[i], pts[j], 8));
  const dentro = (q, r, pad) => q[0] >= r[0] - pad && q[0] <= r[2] + pad && q[1] >= r[1] - pad && q[1] <= r[3] + pad;

  const colocados = [];
  const rotulos = [];
  pp.forEach((p, n) => {
    if (n % 2) return;
    const texto = `10.0.${n + 3}.${12 + n * 7}`;
    const lw = texto.length * 6.7 + 12;
    let melhorR = null;
    let melhorC = Infinity;
    for (const [dx, dy] of [
      [16, -34],
      [16, 16],
      [-lw - 16, -34],
      [-lw - 16, 16],
    ]) {
      const r = [p[0] + dx, p[1] + dy, p[0] + dx + lw, p[1] + dy + 18];
      if (r[0] < 8 || r[2] > w - 8 || r[1] < 8 || r[3] > h - 8) continue;
      if (r[0] < 276 && r[1] < 58) continue;
      if (r[2] > w - 276 && r[3] > h - 58) continue;
      if (ptsCaminho.some((q) => dentro(q, r, 5))) continue;
      if (pts.some((q) => dentro(q, r, 9))) continue;
      if (colocados.some((o) => !(r[2] < o[0] - 6 || r[0] > o[2] + 6 || r[3] < o[1] - 6 || r[1] > o[3] + 6))) continue;
      const custo = ptsArestas.filter((q) => dentro(q, r, 0)).length;
      if (custo < melhorC) {
        melhorC = custo;
        melhorR = r;
      }
    }
    if (melhorR) {
      colocados.push(melhorR);
      rotulos.push({ texto, r: melhorR });
    }
  });

  return { pts, pp, lista, rotulos };
}

export function RedeArte({ semente = 7, w = 856, h = 440, fig = 1 }) {
  const id = useId().replace(/:/g, '');
  const g = useMemo(() => montarRede(semente, w, h), [semente, w, h]);
  const num = String(fig).padStart(2, '0');
  return (
    <svg viewBox={`0 0 ${w} ${h}`} role="img" aria-label="Ilustração: rede de nós com uma rota destacada em vermelho">
      <rect width={w} height={h} fill={C.fundo} />
      <Pontos id={id} w={w} h={h} />
      {g.lista.map(([i, j]) => (
        <line key={`${i}-${j}`} x1={g.pts[i][0]} y1={g.pts[i][1]} x2={g.pts[j][0]} y2={g.pts[j][1]} stroke={C.aresta} strokeWidth="1" />
      ))}
      {g.pts.map(([x, y], i) => (
        <circle key={i} cx={x} cy={y} r="3.5" fill={C.no} />
      ))}
      <polyline
        points={g.pp.map((p) => p.join(',')).join(' ')}
        fill="none"
        stroke={C.acento}
        strokeWidth="3"
        strokeLinejoin="round"
        strokeLinecap="round"
      />
      {g.pp.slice(0, -1).map((a, i) => {
        const b = g.pp[i + 1];
        return <rect key={i} x={(a[0] + b[0]) / 2 - 4} y={(a[1] + b[1]) / 2 - 4} width="8" height="8" fill={C.tinta} />;
      })}
      {g.pp.map(([x, y], i) => (
        <g key={i}>
          <circle cx={x} cy={y} r="12" fill="none" stroke={C.acentoEscuro} strokeWidth="1.5" />
          <circle cx={x} cy={y} r="6.5" fill={C.acento} />
        </g>
      ))}
      {g.rotulos.map(({ texto, r }) => (
        <g key={texto}>
          <rect x={r[0]} y={r[1]} width={r[2] - r[0]} height="18" fill={C.fundo} />
          <text x={r[0] + 6} y={r[1] + 13} className="arte-txt">
            {texto}
          </text>
        </g>
      ))}
      <Legenda x={14} y={12} texto={`FIG. ${num} · TOPOLOGIA`} />
      <Legenda x={w - 14} y={h - 30} texto={`N = ${g.pts.length} · ROTA ${num}`} direita />
      <Cruz x={w - 22} y={22} />
      <Cruz x={22} y={h - 22} />
    </svg>
  );
}

/* ------------------------------------------------------------- cartões */
const W = 306;
const H = 196;

function Moldura({ children, rotulo }) {
  return (
    <svg viewBox={`0 0 ${W} ${H}`} role="img" aria-label={rotulo}>
      <rect width={W} height={H} fill={C.fundo} />
      {children}
    </svg>
  );
}

function AneisArte({ fig }) {
  const cx = W * 0.74;
  const cy = H * 1.02;
  const raios = [];
  for (let r = 26; r < 420; r += 24) raios.push(r);
  const id = useId().replace(/:/g, '');
  return (
    <Moldura rotulo="Ilustração: anéis concêntricos com um anel destacado">
      <Pontos id={id} w={W} h={H} passo={22} />
      {raios.map((r, n) => (
        <circle key={r} cx={cx} cy={cy} r={r} fill="none" stroke={n === 5 ? C.acento : C.anel} strokeWidth={n === 5 ? 2 : 1} />
      ))}
      <circle cx={cx} cy={cy} r="4" fill={C.tinta} />
      <Legenda x={10} y={10} texto={`FIG. ${fig} · CAMADAS`} />
    </Moldura>
  );
}

function BarrasArte({ fig }) {
  const barras = useMemo(() => {
    const r = rng(4);
    let v = 0.4;
    return Array.from({ length: 26 }, () => {
      v = Math.max(0.12, Math.min(0.9, v + (r() * 0.4 - 0.2)));
      return v;
    });
  }, []);
  const base = H - 24;
  const bw = (W - 40) / barras.length;
  const topo = barras.indexOf(Math.max(...barras));
  return (
    <Moldura rotulo="Ilustração: histograma com uma barra destacada">
      {barras.map((v, i) => {
        const hh = v * (H - 80);
        return <rect key={i} x={20 + i * bw + 2} y={base - hh} width={bw - 5} height={hh} fill={i === topo ? C.acento : C.barra} />;
      })}
      <line x1="20" y1={base + 4} x2={W - 20} y2={base + 4} stroke={C.regua} strokeWidth="1" />
      <Legenda x={10} y={10} texto={`FIG. ${fig} · PACOTES`} />
    </Moldura>
  );
}

function SemitomArte({ fig }) {
  const pontos = useMemo(() => {
    const f = [W * 0.3, H * 0.66];
    const lista = [];
    for (let gx = 11; gx < W; gx += 15) {
      for (let gy = 11; gy < H; gy += 15) {
        const dist = Math.hypot(gx - f[0], gy - f[1]);
        let r = Math.max(0, 5.6 - dist / 24);
        if (r < 0.6) r = 0.9;
        lista.push({ gx, gy, r, cor: dist < 52 ? C.acento : dist < 150 ? C.no : '#222530' });
      }
    }
    return lista;
  }, []);
  return (
    <Moldura rotulo="Ilustração: matriz de pontos com um foco vermelho">
      {pontos.map((p, i) => (
        <circle key={i} cx={p.gx} cy={p.gy} r={p.r} fill={p.cor} />
      ))}
      <Legenda x={10} y={10} texto={`FIG. ${fig} · DENSIDADE`} />
    </Moldura>
  );
}

function CurvasArte({ fig }) {
  const caminhos = useMemo(
    () =>
      Array.from({ length: 15 }, (_, i) => {
        const y0 = 34 + i * 11.2;
        let d = '';
        for (let x = 0; x <= W; x += 3) {
          const y = y0 + (6 + i * 0.9) * Math.sin(x / 46 + i * 0.32) + 9 * Math.sin(x / 19 + i * 0.5) * (i / 15);
          d += `${x === 0 ? 'M' : 'L'}${x},${y.toFixed(1)} `;
        }
        return d;
      }),
    []
  );
  return (
    <Moldura rotulo="Ilustração: curvas de nível com uma linha destacada">
      {caminhos.map((d, i) => (
        <path key={i} d={d} fill="none" stroke={i === 8 ? C.acento : C.barra} strokeWidth={i === 8 ? 2 : 1} />
      ))}
      <Legenda x={10} y={10} texto={`FIG. ${fig} · SINAL`} />
    </Moldura>
  );
}

/* ----------------------------------------------- componente público */
// tipo: 'network' | 'rings' | 'bars' | 'halftone' | 'contour'
export default function Arte({ tipo = 'rings', semente = 7, fig = 1 }) {
  const n = String(fig).padStart(2, '0');
  let conteudo;
  if (tipo === 'network') conteudo = <RedeArte semente={semente} fig={fig} />;
  else if (tipo === 'bars') conteudo = <BarrasArte fig={n} />;
  else if (tipo === 'halftone') conteudo = <SemitomArte fig={n} />;
  else if (tipo === 'contour') conteudo = <CurvasArte fig={n} />;
  else conteudo = <AneisArte fig={n} />;
  return <figure className="arte">{conteudo}</figure>;
}
