import { Link } from 'react-router-dom';
import Arte from '../Arte/Arte.jsx';
import Seta from '../Seta/Seta.jsx';
import { hash } from '../../lib/util.js';

export default function PostCard({ post, fig = 2 }) {
  const url = `/artigo/${post.slug}`;
  return (
    <article className="card">
      <Link to={url} className="card-arte" tabIndex={-1} aria-hidden="true">
        <Arte tipo={post.arte} semente={hash(post.slug)} fig={fig} />
      </Link>
      <p className="rotulo acc">
        {post.tipo === 'tutorial' ? 'Tutorial' : 'Artigo'} · {post.topico}
      </p>
      <h3>
        <Link to={url}>{post.titulo}</Link>
      </h3>
      <p className="card-resumo">{post.resumo}</p>
      <Link className="lnk" to={url}>
        Ler {post.tipo === 'tutorial' ? 'tutorial' : 'artigo'} <Seta />
      </Link>
    </article>
  );
}
