import { Link, NavLink } from 'react-router-dom';
import { site } from '../../data/site.js';

const itens = [
  ['/artigos', 'Artigos'],
  ['/projetos', 'Projetos'],
  // ['/forum', 'Fórum'],
  // ['/tutoriais', 'Tutoriais'],
  ['/sobre', 'Sobre'],
];

export default function Header() {
  return (
    <header className="topo">
      <div className="wrap nav-in">
        
        <Link to="/" className="marca" aria-label={`${site.nome}, página inicial`}>
          {site.nome}
          <i className="pt" aria-hidden="true" />
        </Link>
        <nav className="nav" aria-label="Principal">
          {itens.map(([to, texto]) => (
            <NavLink key={to} to={to} className={({ isActive }) => (isActive ? 'ativo' : '')}>
              {texto}
            </NavLink>
          ))}
        </nav>
      </div>
    </header>
  );
}
